/* 안전의 달인 — 시간·하트·경쟁점수 없이 연습하는 현장학습 안전교육 */
(()=>{
'use strict';
const C=globalThis.TripContent,M=globalThis.TripModel,G=globalThis.SafetyMiniGames,A=globalThis.SafetyActivities,R=globalThis.TripResources||{videos:[],activities:[],sources:[],meta:{}};
const $=s=>document.querySelector(s),main=$('#main'),dialog=$('#dialog');
const BASE=new URL('./',document.baseURI).href;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=p=>p?.startsWith('img/')?p.replace(/^img\//,'media/').replace(/\.png$/,'.webp'):p;
const scene=id=>`media/illustrations/${id}.webp`;
function saved(){try{return JSON.parse(localStorage.getItem('safetyMasterSettings'))||{};}catch{return {};}}
let pref={pictures:true,large:false,voice:true,motion:!(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches),...saved()};
let config=M.parseLocation(location.href,C),chosenType=!!new URL(location.href).searchParams.get('type'),session=null;
let page=config.place?'place':'home',feedback=null,goalAnswered=false,pledge='',aacTab=0,dialogKind='',returnFocus=null,toastTimer;
let resourcePage=0,resourceFilter={place:config.place||'',domain:'',level:'',query:''},resourceMode='related',returnPage='home';
const hints=new Set();let goalChoice=null;const selectedReports=new Set();
let activityProgress={},world=null;
if(pref.remember){try{const saved=JSON.parse(localStorage.getItem('safetyMasterActivities'));if(saved&&typeof saved==='object'&&!Array.isArray(saved)){for(const id of Object.keys(C.places)){const data=saved[id];if(data&&typeof data==='object'){activityProgress[id]={};for(const a of A.plans[id]||[])if(data[a.id]&&typeof data[a.id]==='object')activityProgress[id][a.id]={assisted:!!data[a.id].assisted,at:typeof data[a.id].at==='string'?data[a.id].at.slice(0,40):''};}}}}catch{}}
const levelName={유:'유치원',초등저:'초등 저학년',초등고:'초등 고학년',중:'중학교',고:'고등학교'};
const preferred={cinema:['compass-0031','compass-0039'],sports:['compass-0098','compass-0106','compass-0109'],experience:['compass-0090','compass-0083'],park:['compass-0612','compass-0613'],garden:['compass-0182'],heritage:['compass-0127','compass-0203','compass-0612'],bus:['compass-0189','compass-0190','compass-0304'],lodging:['compass-0195'],escape:['compass-0502','compass-0504']};
function icon(name){const alias={sun:'day',moon:'overnight',clock:'halfday',route:'start'};return `<img class="ui-icon" src="media/ui/${alias[name]||name}.webp" alt="" aria-hidden="true">`;}
function image(src,alt,cls='',extra=''){return `<img src="${esc(asset(src))}" alt="${esc(alt)}" class="${cls}" loading="lazy" decoding="async" ${extra}>`;}
function button(action,label,cls='',attrs=''){const icons={type:'select',place:'start',home:'home',prepare:'teacher','choose-again':'back',resume:'play','pre-pledge':'goal','begin-goal':'goal','goal-answer':'select','start-learning':'play',spot:'search','spot-read':'read','spot-done':'check','to-game':'play','game-card':'select','game-finish':'check','choose-mini':'play','mini-reset':'again','mini-flip':'picture','mini-match-left':'select','mini-match-right':'select','mini-lane':'next','mini-step':'next','mini-wait':'pause','mini-jump':'play','mini-rest':'pause','mini-find':'search','mini-bright':'hint','mini-move':'next','mini-hazard':'stop','mini-pick':'select','mini-finish':'check','mini-next':'next',answer:'select',hint:'hint','try-again':'again',guided:'teacher','report-check':'check','next-question':'next','next-module':'next',restart:'again',pledge:'goal',settings:'settings',aac:'aac','aac-tab':'picture',say:'read',read:'read',teacher:'teacher','source-info':'review',close:'close',related:'video',resources:'video','all-resources':'video','back-from-resources':'back','resource-next':'next','resource-prev':'back','clear-filters':'again','share-place':'share','share-lesson':'share','share-resources':'share',print:'print',download:'save','review-guided':'review','start-activity':'play','find-target':'search','find-region':'search','find-hint':'hint','find-egg':'search','find-finish':'check','activity-home':'home','activity-result':'result','activity-finish':'check','difference-region':'search','open-world':'start','world-move':'next','world-mission':'play','world-nearest':'search',badge:'result','clear-progress':'again'};const needs=!/<img[\s>]/.test(label)&&!/(?:find-hot|find-egg)/.test(cls);return `<button data-action="${action}" class="${cls} ${needs?'illustrated-button':''}" ${attrs}>${needs?icon(icons[action]||'select'):''}${needs?`<span class="button-label">${label}</span>`:label}</button>`;}
function say(text){if(!pref.voice){notify('소리 읽기가 꺼져 있어요. 학습지원에서 켤 수 있어요.');return;}if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){notify('이 기기에서는 음성을 사용할 수 없어요. 화면의 글과 그림으로 확인해요.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim());u.lang='ko-KR';u.rate=.88;speechSynthesis.speak(u);}
function notify(text){$('#status').textContent=text;$('#status').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').classList.remove('show'),5000);}
function applyPrefs(){document.body.classList.toggle('large-text',!!pref.large);document.body.classList.toggle('picture-mode',!!pref.pictures);document.body.classList.toggle('no-motion',!pref.motion);try{localStorage.setItem('safetyMasterSettings',JSON.stringify(pref));}catch{}}
function typeTitle(){return C.types.find(t=>t.id===config.type)?.title||'현장학습';}
function currentPlace(){return C.places[session?.route[session.index]||config.place];}
function moduleId(){return session?.route[session.index]||config.place;}
function heading(kicker,title,description=''){return `<div class="eyebrow"><span class="dot"></span>${kicker}</div><h1 tabindex="-1">${title}</h1>${description?`<p class="intro">${description}</p>`:''}`;}
function routeTags(route,active){return `<div class="stage-tags" aria-label="오늘의 학습 순서">${route.map((id,i)=>`<span class="tag ${i===active?'active':''}" ${i===active?'aria-current="step"':''}>${i+1}. ${esc(C.places[id].short)}</span>`).join('')}</div>`;}
function phaseNav(phase){const phases=[['explore','살펴봐요'],['choice','게임으로 해봐요'],['quiz','다시 확인해요'],['module-done','약속을 기억해요']];return `<div class="phase-nav" aria-label="장소 안 학습 순서">${phases.map(([id,label],i)=>`<span class="${id===(['play','mini','activity-menu'].includes(phase)?'choice':phase)?'now':''}" ${id===(['play','mini'].includes(phase)?'choice':phase)?'aria-current="step"':''}>${i+1} ${label}</span>`).join('')}</div>`;}
function setPage(next){page=next;feedback=null;render();}
function render(focus=true){
 applyPrefs();document.title=`${config.place?C.places[config.place].short+' · ':''}안전의 달인`;
 const renderers={home:renderHome,place:renderPlace,world:renderWorld,prepare:renderPrepare,goal:renderGoal,learn:renderLearn,result:renderResult,resources:renderResources};
 main.innerHTML=(renderers[page]||renderHome)();
 if(focus){(main.querySelector('h1')||main).focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'});}
}
function storeProgress(){if(!pref.remember)return;try{localStorage.setItem('safetyMasterActivities',JSON.stringify(activityProgress));}catch{notify('이 기기에 기록을 보관할 수 없어요. 지금 수업은 계속할 수 있어요.');}}
function renderBadgeBoard(){return `<section class="explorer-board section" aria-labelledby="badge-title"><div class="section-head"><div><h2 id="badge-title">나의 안전 탐험판</h2><p>장소 그림을 누르면 배울 약속과 연습한 활동을 볼 수 있어요.</p></div>${image('media/brand/mascot.webp','','board-mascot')}</div><div class="badge-grid">${[...C.destinations,"bus",...(config.type==="overnight"?["night","escape",...(config.rest?["rest"]:[])]:[])].map(id=>{const count=Object.keys(activityProgress[id]||{}).length;return button('badge',`<span class="badge-medal ${count?'earned':''}">${image(scene(id),'')}<span class="badge-ribbon">${count?'함께 연습':'탐험할 곳'}</span></span><b>${esc(C.places[id].short)}</b><small>${count?count+'개 활동 연습':'눌러서 살펴봐요'}</small>`,'badge-card',`data-id="${id}"`);}).join('')}</div><p class="muted badge-note">배지는 연습 참여 표시예요. 실제 장소에서도 선생님과 다시 확인해요.</p></section>`;}
function badgeDialog(id){const p=C.places[id],done=activityProgress[id]||{};openDialog('badge',`${dialogHead(esc(p.short)+' 안전 탐험')}<div class="badge-preview">${image(scene(id),'')}<div><h3>기억할 안전 약속</h3><p>${esc(p.spots[0].rule)}</p><p class="muted">${Object.keys(done).length}개 활동을 함께 연습했어요.</p></div></div><div class="actions">${button('place','이 장소 연습하기','primary',`data-id="${id}"`)}</div>`);}
function startActivity(kind,fromWorld=false){const entry=(A.plans[config.place]||[]).find(a=>a.id===kind);if(!entry)return;session=M.createSession({...config,scope:'place',move:'none',rest:false},C);session.single=true;session.activityKind=kind;session.activityTitle=entry.title;session.fromWorld=fromWorld;feedback=null;hints.clear();selectedReports.clear();page='learn';
 if(kind==='find'){session.find={found:[],hint:false,egg:false,assisted:false,attempts:0};session.phase='find';render();}
 else if(kind==='difference'){session.difference={found:[],hint:false,assisted:false};session.phase='difference';render();}
 else if(kind==='choice'||kind==='quiz'){session.phase=kind;render();}
 else chooseActivity(entry.kind);
}
function finishActivity(assisted=false){const id=moduleId(),kind=session.activityKind;if(!session.single){startChoice();return;}const guided=assisted||!!session.find?.assisted||!!session.difference?.assisted||session.records.some(r=>r.assisted);activityProgress[id]??={};activityProgress[id][kind]={assisted:guided,at:new Date().toISOString()};session.activityAssisted=guided;session.phase='activity-done';M.completeModule(session,id);storeProgress();render();}
function renderActivityDone(){const id=moduleId();return `<section class="panel activity-done"><div class="completion-portrait">${image('media/brand/mascot.webp','함께 연습한 형아맨')}${icon('result')}</div><h2>${esc(session.activityTitle)}<br>함께 연습했어요!</h2><p>${session.activityAssisted?'선생님과 도움을 받아 확인했어요.':'천천히 끝까지 활동했어요.'}</p><p class="intro">실제 장소에서도 선생님과 안전 약속을 확인해요.</p><div class="actions">${button('activity-home',session.fromWorld?'탐험 지도로 돌아가기':'다른 활동 고르기','primary')}${button('activity-result','결과와 나의 약속','secondary')}${button('related','관련 영상 보기','secondary',`data-id="${id}"`)}</div></section>`;}
function renderFind(){const id=moduleId(),f=A.finds[id],g=session.find;return `<section class="find-game"><h2 tabindex="-1">${esc(f.title)}</h2><p>그림 속에서 안전을 확인할 곳을 직접 눌러요. 아래 영역 버튼으로도 찾을 수 있어요.</p><div class="find-scene ${g.hint?'show-hints':''}" id="find-scene">${image(f.image||scene(id),C.places[id].title+' 안전 지점을 찾는 그림')}${f.targets.map(t=>{const [x,y,w,h]=t.box;return button('find-target',`<span class="sr-only">${esc(t.label)} ${g.found.includes(t.id)?'찾았어요':'찾기'}</span>${g.found.includes(t.id)?icon('check'):''}`,`find-hot ${g.found.includes(t.id)?'found':''}`,`data-id="${t.id}" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"`);}).join('')}${f.egg?button('find-egg','<span class="sr-only">숨은 관찰 그림 '+esc(f.egg.label)+'</span>','find-egg',`style="left:${f.egg.box[0]}%;top:${f.egg.box[1]}%;width:${f.egg.box[2]}%;height:${f.egg.box[3]}%"`):''}</div><div class="find-checks" aria-label="찾을 안전 지점">${f.targets.map(t=>`<span class="${g.found.includes(t.id)?'found':''}">${g.found.includes(t.id)?icon('check'):icon('search')}${esc(t.label)}</span>`).join('')}</div><p class="mini-notice" role="status">${esc(g.notice||'안전 지점 '+g.found.length+' / '+f.targets.length+' 찾았어요.')}</p><div class="actions">${button('find-hint',g.hint?'그림 힌트 끄기':'그림에 힌트 보기','secondary')}${button('find-finish','점검 완료','primary',g.found.length===f.targets.length?'':'disabled')}</div><details class="region-alternatives"><summary>영역 버튼으로 살펴보기</summary><p>작은 그림을 누르기 어려우면 아래 버튼으로 같은 활동을 해요.</p><div class="actions">${f.targets.map(t=>button('find-region',esc(t.label)+' 위치 살펴보기','secondary',`data-id="${t.id}"`)).join('')}</div></details></section>`;}
function foundTarget(id,assisted=false){const target=A.finds[moduleId()]?.targets.find(t=>t.id===id);if(!target)return;const g=session.find;g.attempts++;if(!g.found.includes(id))g.found.push(id);g.assisted=g.assisted||assisted||g.hint;g.notice=target.label+' 위치를 찾았어요!';render(false);openDialog('find-rule',`${dialogHead(esc(target.label)+' 발견!')}<div class="spot-detail">${aacImage(target.signal)}<p>${esc(target.rule)}</p></div>${button('close','기억할게요','primary wide')}`);}
const differences=[{id:'board',label:'침대 위 물건',box:[3,31,32,56],signal:'rest',rule:'침대 위에 걸려 넘어질 물건을 두지 않고 정해진 곳에 보관해요.'},{id:'bag',label:'통로의 가방',box:[39,41,24,49],signal:'bag',rule:'가방과 신발은 이동 통로를 막지 않는 정해진 곳에 놓아요.'},{id:'cup',label:'바닥의 컵과 물기',box:[75,54,20,43],signal:'help',rule:'쏟아진 물은 선생님께 알려요. 젖은 바닥을 피하고 안전하게 정리한 뒤 이동해요.'}];
function renderDifference(){const g=session.difference;return `<section class="difference-game"><h2 tabindex="-1">안전하게 정리한 곳, 세 군데를 찾아요</h2><p>두 그림을 비교해 바뀐 곳을 눌러요. 어느 그림을 눌러도 괜찮아요.</p><div class="difference-pair">${['before','after'].map((which,i)=>`<div><h3>${i?'정리한 뒤':'정리하기 전'}</h3><div class="find-scene ${g.hint?'show-hints':''}" data-difference-scene>${image('media/game/room-'+which+'.webp',i?'침대 위 물건·가방·컵을 정해진 곳에 정리한 숙소':'침대 위 물건, 통로의 가방, 바닥에 쏟아진 물이 있는 숙소')}${differences.map(d=>button('difference-region',`<span class="sr-only">${esc(d.label)} 비교 영역</span>${g.found.includes(d.id)?icon('check'):''}`,`find-hot ${g.found.includes(d.id)?'found':''}`,`data-id="${d.id}" style="left:${d.box[0]}%;top:${d.box[1]}%;width:${d.box[2]}%;height:${d.box[3]}%"`)).join('')}</div></div>`).join('')}</div><p class="mini-notice" role="status">바뀐 안전 지점 ${g.found.length} / 3 찾았어요.</p><div class="actions">${button('find-hint',g.hint?'힌트 끄기':'바뀐 영역 힌트','secondary')}${button('activity-finish','세 곳 확인 완료','primary',g.found.length===3?'':'disabled')}</div><details class="region-alternatives"><summary>그림 영역 버튼으로 비교하기</summary><div class="actions">${differences.map(d=>button('difference-region',esc(d.label)+' 비교','secondary',`data-id="${d.id}" data-assisted="true"`)).join('')}</div></details></section>`;}
function renderWorld(){const p=C.places[config.place],w=A.worlds[config.place];return `${heading('형아맨과 함께하는 장소 탐험',esc(w.title),'미션 그림을 바로 눌러도 되고, 형아맨을 이동시켜 살펴봐도 좋아요.')}<div class="world-field" id="world-field" tabindex="0" role="group" aria-label="방향키로 이동하는 연습 지도. 미션은 아래 큰 버튼으로도 선택할 수 있어요.">${image('media/maps/'+config.place+'.webp',p.title+' 탐험 배경. 아래쪽은 안전한 이동 연습 구역이에요.','world-background')}${w.activities.map((kind,i)=>{const a=A.plans[config.place].find(a=>a.id===kind),done=activityProgress[config.place]?.[kind];return button('world-mission',`${icon(done?'check':a.icon)}<span>${i+1}. ${esc(a.title)}</span>`,'world-marker',`data-kind="${kind}" style="left:${[19,50,81][i]}%;top:50%"`);}).join('')}${image('media/illustrations/sprite-hero.png','안전한 이동 구역에 있는 형아맨','world-hero',`style="left:${world.x}%;top:${world.y}%"`)}<span class="world-safe-label">안전한 이동 연습 구역</span></div><p class="scene-caption">실제 시설의 배치도와 다른 연습 지도예요. 실제 비상구·물가·이용 구역은 현장에서 확인해요.</p><div class="world-controls" aria-label="형아맨 이동"><div class="direction-pad">${[['left','왼쪽',-8,0],['up','위쪽',0,-5],['down','아래쪽',0,5],['right','오른쪽',8,0]].map(([dir,label,dx,dy])=>button('world-move',label,'secondary direction-'+dir,`data-dx="${dx}" data-dy="${dy}"`)).join('')}</div>${button('world-nearest','가까운 미션 살펴보기','primary')}${button('activity-home','장소 활동 목록','secondary')}</div><p id="world-position" class="sr-only" aria-live="polite"></p><div class="activity-choice-grid section">${w.activities.map(kind=>{const a=A.plans[config.place].find(a=>a.id===kind);return button('world-mission',`${icon(a.icon)}<span>${esc(a.title)}<small>${esc(a.goal)}</small></span>`,'activity-choice',`data-kind="${kind}"`);}).join('')}</div>`;}
function moveWorld(dx,dy){world.x=Math.max(8,Math.min(92,world.x+dx));world.y=Math.max(73,Math.min(92,world.y+dy));const hero=main.querySelector('.world-hero');hero.style.left=world.x+'%';hero.style.top=world.y+'%';$('#world-position').textContent=world.x<35?'왼쪽 이동 구역':world.x>65?'오른쪽 이동 구역':'가운데 이동 구역';}
function renderHome(){return `<section class="hero"><div>${heading('함께 배우는 현장학습 안전','<span class="sr-only">안전의 달인</span>'+image('media/brand/wordmark.webp','','hero-wordmark','fetchpriority="high"'),'함께 배우고, 안전하게 다녀와요.<br>그림·게임·퀴즈로 안전을 연습해요.')}<div class="flow" aria-label="학습 흐름"><span>${icon("start")}장소 선택</span><span>${icon("play")}필요한 활동</span><span>${icon("result")}나의 약속</span></div></div><div class="hero-art">${image('media/illustrations/guide.webp','형아맨과 선생님이 안전 약속을 함께 안내해요.','','fetchpriority="high"')}<span class="speech">모르면 같이 해요!</span></div></section>
 ${session&&session.completed.length<session.route.length?`<div class="info">진행하던 ${esc(C.places[session.config.place].title)} 수업이 있어요. ${button('resume','이어서 하기','secondary')}</div>`:''}
 <section aria-labelledby="type-title"><div class="section-head"><div><h2 id="type-title">어떤 현장학습을 가나요?</h2><p>먼저 현장학습 유형을 골라요.</p></div></div><div class="type-grid">${C.types.map(t=>button('type',`<span class="type-icon">${icon(t.icon)}</span><span><b>${t.title}</b><small>${t.subtitle}</small></span>`,`type-card ${chosenType&&config.type===t.id?'selected':''}`,`data-id="${t.id}" aria-pressed="${chosenType&&config.type===t.id}"`)).join('')}</div></section>
 ${chosenType?`<section class="section" id="places" aria-labelledby="places-title"><div class="section-head"><div><h2 id="places-title" tabindex="-1">어디로 가나요?</h2><p>이번에 방문할 장소를 하나 골라요.</p></div><span class="tag">${esc(typeTitle())}</span></div><div class="place-grid">${C.destinations.filter(id=>id!=='lodging'||config.type==='overnight').map(id=>{const p=C.places[id];return button('place',`${image(scene(id),'')}<span class="card-copy"><span class="arrow" aria-hidden="true">${icon('next')}</span><b>${p.title}</b><small>${p.example}</small></span>`,'place-card',`data-id="${id}" aria-label="${esc(p.title)}. ${esc(p.example)}"`);}).join('')}</div></section>`:''}${renderBadgeBoard()}`;}
function renderPlace(){const p=C.places[config.place],plan=A.plans[config.place]||[],lead=plan[0];return `<div class="lesson-top"><div>${heading(esc(typeTitle()),esc(p.title)+' 안전 탐험',esc(p.description))}</div>${button('choose-again','장소 다시 고르기','secondary')}</div><div class="venue-intro"><div>${image(scene(config.place),p.title+' 안전교육 그림','pre-photo')}</div><section class="panel soft"><p class="eyebrow">오늘 여기서 연습해요</p><h2>${esc(lead?.title||'안전 약속')}</h2><p class="intro">${esc(lead?.goal||p.description)}</p>${lead?button('start-activity',esc(lead.title)+' 시작','primary wide',`data-kind="${lead.id}"`):''}${A.worlds[config.place]?button('open-world','형아맨과 장소 탐험하기','secondary wide'):''}<p class="muted">그림·게임·영상 중 필요한 활동을 골라요.<br>모든 활동을 순서대로 할 필요는 없어요.</p></section></div><section class="section" aria-labelledby="activity-title"><div class="section-head"><div><h2 id="activity-title">이 장소에서 무엇을 해볼까요?</h2><p>우리 반에 필요한 활동을 골라요.</p></div></div><div class="activity-choice-grid">${plan.map(a=>button('start-activity',`<span class="activity-visual">${icon(a.icon)}</span><span><b>${esc(a.title)}</b><small>${esc(a.goal)}</small>${activityProgress[config.place]?.[a.id]?'<small class="practiced">함께 연습했어요</small>':''}</span>`,'activity-choice',`data-kind="${a.id}"`)).join('')}</div>${videoCta(config.place)}</section><details class="section panel teacher-tools"><summary>선생님 · 목표와 연결 수업</summary><ul>${p.spots.map(s=>`<li>${esc(s.rule)}</li>`).join('')}</ul><p class="muted">여러 장소를 이어서 진행할 때 사용해요. 버스와 휴게소는 선생님 수업 도구에서 일정에 맞게 추가해요.</p><div class="actions">${button('prepare','선택한 일정으로 연결 수업','secondary')}${button('teacher','일정·자료 설정','secondary')}</div></details><div class="actions no-print">${button('share-place','이 장소 주소 공유','secondary')}${button('share-lesson','연결 수업 주소 공유','secondary')}</div>`;}

function videoCta(id){return `<aside class="video-cta"><div><strong>영상으로도 알아봐요</strong><p>${id==='heritage'?'관람 전 함께 볼 공통 안전 영상':'이 장소와 관련된 안전 영상'}을 볼 수 있어요.</p></div>${button('related','관련 영상 보기','secondary',`data-id="${id}"`)}</aside>`;}
function renderPrepare(){const p=C.places[config.place];return `${heading('선생님과 연결 수업','오늘의 안전 약속','필요한 장소를 이어서 연습해요.')}<div class="pre-layout section"><section class="panel"><h2>도움이 필요하면 알려요.</h2><div class="pledge">${[['hurt','아프거나 불편하면 알려요.'],['unknown','모르면 다시 물어봐요.'],['together','정해진 곳에서 함께 움직여요.']].map(([key,text])=>button('pre-pledge',`${aacImage(key)}<span>${text}</span>`,'',`data-key="${key}" aria-pressed="false"`)).join('')}</div><p class="muted">약속 카드는 선택해서 들어요. 누르지 않아도 시작할 수 있어요.</p></section><section class="panel"><h3>선택한 수업</h3><p>${esc(typeTitle())} · ${esc(p.title)}</p>${routeTags(M.routeFor(config,C),-1)}<p class="muted">버스·휴게소 추가는 선생님 수업 도구에서만 설정해요.</p><div class="actions">${button('begin-goal','목표 확인하고 시작','primary')}${button('teacher','일정 바꾸기','secondary')}</div></section></div>`;}

function goalQuestion(){const p=C.places[config.place];return p.choices[0]||C.evacuation[0];}
function renderGoal(){const p=C.places[config.place],q=goalQuestion();return `${heading('목표 확인 · 처음 생각해 봐요',esc(p.short)+'에서 어떻게 할까요?','정답을 몰라도 괜찮아요. 함께 알아봐요.')}<div class="question-layout section"><div class="question-visual">${image(scene(config.place),p.title+' 상황을 살펴보는 안내 그림','question-image')}</div><section class="question-box"><h2 class="q-text">${esc(q.prompt)}</h2>${goalAnswered?`<div class="feedback"><h3>오늘 함께 연습할 행동이에요.</h3><p>${esc(q.why)}</p>${button('start-learning','게임으로 연습하기','primary wide')}</div>`:options(q,'goal-answer')}</section></div>`;}
function moduleQuestions(id){return id==='escape'?C.evacuation:C.places[id].choices;}
function currentQuestion(){if(page==='goal')return goalQuestion();const id=moduleId();return session.phase==='quiz'?C.places[id].quizzes[session.questionIndex]:moduleQuestions(id)[session.questionIndex];}
function questionKey(){return `${moduleId()}/${session?.phase}/${session?.questionIndex}`;}
function options(q,action='answer'){return `<div class="options">${q.options.map((text,i)=>button(action,`<span class="letter" aria-hidden="true">${i+1}</span><span>${esc(text)}</span>`,'option',`data-index="${i}"`)).join('')}</div>`;}
function renderLearn(){const id=moduleId(),p=C.places[id],phase=session.phase;const progress=Math.round(session.completed.length/session.route.length*100);let body='';
 if(phase==='explore')body=`<div class="learn-layout"><div>${image(scene(id),p.title+'에서 선생님과 안전한 행동을 확인하는 그림','pre-photo')}<p class="scene-caption">그림을 살펴보고, 안전 약속 카드를 하나씩 골라요.</p>${videoCta(id)}</div><section><div class="spot-list">${p.spots.map((s,i)=>button('spot',`<span class="num" aria-hidden="true">${session.spotIds.includes(s.id)?icon('check'):i+1}</span><span>${esc(s.title)}<small>${session.spotIds.includes(s.id)?'함께 확인했어요':'눌러서 약속을 확인해요'}</small></span>`,`spot-button ${session.spotIds.includes(s.id)?'done':''}`,`data-id="${s.id}" aria-label="${esc(s.title)}${session.spotIds.includes(s.id)?', 확인 완료':''}"`)).join('')}</div><p class="muted" style="margin-top:17px">안전 약속 ${session.spotIds.length} / ${p.spots.length} 확인</p>${button('to-game','상황 게임으로 가기','primary wide',`${session.spotIds.length!==p.spots.length?'disabled':''} style="margin-top:22px"`)}</section></div>`;
 else if(phase==='module-done')body=`<section class="panel soft"><h2>${esc(p.short)} 미션을 함께 마쳤어요!</h2><ul>${p.spots.map(s=>`<li style="margin:16px 0">${esc(s.rule)}</li>`).join('')}</ul>${button('next-module',session.index<session.route.length-1?'다음 안전 미션으로':'결과와 나의 약속 보기','primary wide')}</section>`;
 else if(phase==='find')body=renderFind();
 else if(phase==='difference')body=renderDifference();
 else if(phase==='activity-done')body=renderActivityDone();
 else if(phase==='play')body=renderPreparationGame();
 else if(phase==='activity-menu')body=renderActivityMenu();
 else if(phase==='mini')body=renderMiniGame();
 else body=renderQuestion();
 if(session.single)return `<div class="lesson-top"><div>${heading(esc(p.title),esc(session.activityTitle),phase==='activity-done'?'':'필요한 도움을 받으며 천천히 해봐요.')}</div>${button('activity-home',session.fromWorld?'탐험 지도로':'다른 활동 고르기','secondary')}</div>${body}`;
 return `<div class="progress" aria-hidden="true"><span style="width:${progress}%"></span></div><p class="progress-label">오늘의 수업 ${session.index+1} / ${session.route.length} · ${esc(typeTitle())}</p><div class="lesson-top"><div>${heading(phase==='quiz'?'확인 퀴즈':id==='escape'?'대피 상황을 연습해요':'함께 해결하는 안전 미션',esc(p.title),phase==='explore'?esc(p.description):'')}</div>${button('related','관련 영상 보기','secondary',`data-id="${id}"`)}</div>${phaseNav(phase)}${body}`;
}
function renderPreparationGame(){const id=moduleId(),p=C.places[id];const cards=p.spots;const wrong={sports:'위험한 공중제비 하기',cinema:'혼자 밖으로 나가기',museum:'말없이 다른 전시실로 가기',experience:'모르는 도구를 바로 만지기','theme-park':'울타리 넘어 물건 줍기',park:'호수 가장자리로 내려가기',garden:'모르는 열매 맛보기',heritage:'출입 금지 줄 넘어가기',lodging:'침대에서 뛰기',bus:'달리는 버스에서 일어나기',rest:'말없이 주차장 건너가기',night:'불편해도 혼자 참기'}[id];
 const order=[cards[0],{id:'unsafe',title:wrong},cards[1],cards[2]];
 return `<section class="preparation-game" aria-labelledby="game-title"><div class="game-copy"><div class="eyebrow">안전 준비 게임</div><h2 id="game-title" tabindex="-1">안전한 행동을 골라<br>준비 칸을 채워요.</h2><p class="intro">${esc(p.short)}에서 할 행동 3가지를 골라요.</p><div class="game-slots" aria-label="안전 준비 ${session.gameCards.length}개 완료">${cards.map((s,i)=>`<div class="game-slot ${session.gameCards.includes(s.id)?'filled':''}"><span class="slot-number">${i+1}</span>${session.gameCards.includes(s.id)?`<span>✓ ${esc(s.title)}</span>`:'<span>안전 행동을 골라요</span>'}</div>`).join('')}</div><p class="game-notice" role="status">${esc(session.gameNotice||'눌러서 골라요. 천천히 생각해도 괜찮아요.')}</p>${button('game-finish','준비 완료! 상황 속으로','primary wide',session.gameCards.length===3?'':'disabled')}</div><div class="game-board">${image(scene(id),p.title+' 안전 준비 장면','question-image')}<div class="game-card-grid">${order.map(s=>button('game-card',`${s.id!=='unsafe'?aacImage(s.signal):`<span class="game-symbol" aria-hidden="true">?</span>`}<span>${esc(s.title)}</span>`,'game-card',`data-id="${s.id}" ${session.gameCards.includes(s.id)?'disabled':''}`)).join('')}</div></div></section>`;}
function renderActivityMenu(){return `<section class="activity-menu"><div class="section-head"><div><h2 tabindex="-1">어떤 활동을 해볼까요?</h2><p>오늘의 안전 약속을 재미있게 연습해요.</p></div></div><div class="activity-choice-grid">${G.catalog(moduleId()).map(g=>button('choose-mini',`<span class="activity-visual">${icon(g.icon)}</span><span><b>${esc(g.title)}</b><small>${esc(g.goal)}</small></span>`,'activity-choice',`data-kind="${g.id}"`)).join('')}</div><div class="actions">${button('mini-next','상황 문제로 바로 가기','secondary')}</div></section>`;}
function renderMiniGame(){const g=session.mini;let board='',controls='',title='',description='';
 if(g.kind==='sequence'){const seq=G.sequences[g.sequence];title=seq.title;description=seq.description;board=`<div class="sequence-slots" aria-label="確認한 순서">${seq.cards.map((c,i)=>`<div class="game-slot ${i<g.step?'filled':''}"><span>${i+1}</span>${i<g.step?esc(c[1]):'다음 할 일을 골라요'}</div>`).join('')}</div><div class="sequence-cards">${g.order.map(i=>button('mini-pick',`${aacImage(seq.cards[i][0])}<span>${esc(seq.cards[i][1])}</span>`,'game-card',`data-index="${i}" ${i<g.step?'disabled':''}`)).join('')}</div>`;}
 if(g.kind==='jump'){title='내 차례! 점프 미션';description='내 차례에 점프 5회, 마지막에는 휴식해요.';board=`<div class="jump-field ${g.phase==='wait'?'waiting':''}"><div class="jump-count">점프 ${g.count} / 5</div><div class="jump-pad" aria-hidden="true"></div>${g.phase==='wait'?'<div class="friend-token" role="img" aria-label="친구가 먼저 이용하고 있어요">친구 차례</div>':''}${image('media/illustrations/sprite-hero.png','점프하는 형아맨','jump-hero','id="jump-hero"')}<div class="jump-shadow" aria-hidden="true"></div></div>`;controls=g.complete?'':g.phase==='wait'?button('mini-wait','차례를 기다려요','primary wide'):g.phase==='rest'?button('mini-rest','쉬고 싶어요','primary wide'):button('mini-jump','터치해서 점프!','primary wide jump-button',g.inAir?'disabled':'');}
 if(g.kind==='torch'){title='손전등으로 안전장치 찾기';description='소화기 · 화재경보기 · 비상구 유도등, 3곳을 찾아요.';board=`<div class="torch-field" id="torch-field" aria-label="손전등으로 살펴보는 숙소 복도">${image('media/trip08_corridor.webp','숙소 복도. 왼쪽 벽에 소화기, 가운데 벽에 화재경보기, 오른쪽 위에 비상구 유도등이 있어요.')}<div class="torch-shade ${g.bright?'bright':''}" aria-hidden="true"></div>${G.targets.map(t=>`<span class="torch-mark ${g.found.includes(t.id)?'found':''}" style="left:${t.x}%;top:${t.y}%" aria-hidden="true">✓</span>`).join('')}</div><p class="scene-caption">화면을 움직이거나 터치해서 찾아요. 아래 영역 버튼으로도 같은 미션을 할 수 있어요.</p>`;controls=`<div class="torch-areas">${G.targets.map(t=>button('mini-find',`${g.found.includes(t.id)?'✓ ':''}${t.area}`,'secondary',`data-id="${t.id}" ${g.found.includes(t.id)?'disabled':''}`)).join('')}</div>${button('mini-bright',g.bright?'손전등으로 보기':'화면 전체 밝게 보기','secondary wide')}`;}
 if(g.kind==='path'){title='안전한 길을 완성해요';description='다음 지점 3곳을 차례대로 골라 목적지에 도착해요.';const pts=[[18,72],[43,50],[70,29]];const positions=[[5,86],...pts];board=`<div class="path-field"><svg class="path-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M5 86 18 72 43 50 70 29" fill="none" stroke="#94cbb9" stroke-width="3" stroke-dasharray="3 3"/></svg>${G.pathLabels[g.place].map((t,i)=>button('mini-move',`${i<g.step?'✓':i+1}<small>${esc(t)}</small>`,`path-stop ${i<g.step?'reached':''}`,`data-index="${i}" style="left:${pts[i][0]}%;top:${pts[i][1]}%" ${i<g.step?'disabled':''}`)).join('')}${button('mini-hazard','출입 제한 구역','path-hazard')}${image('media/illustrations/sprite-hero.png','안전한 길을 이동하는 형아맨','path-hero',`style="left:${positions[g.step][0]}%;top:${positions[g.step][1]}%"`)}<span class="path-goal">목적지</span></div><p class="scene-caption">안전한 이동을 연습하는 게임 지도예요. 실제 시설의 배치도와는 달라요.</p>`;}
 if(g.kind==='memory'){title='같은 안전 그림을 찾아요';description='같은 그림 세 쌍을 찾아 카드를 모두 펼쳐요.';board=`<div class="memory-grid">${g.cards.map((c,i)=>{const face=g.open.includes(i)||g.matched.includes(c.key);return button('mini-flip',`${face?aacImage(c.key):image('media/brand/mascot.webp','')}<span>${face?esc(C.aac[c.key]):'그림 열기'}</span>`,`memory-card ${face?'face-up':''} ${g.matched.includes(c.key)?'matched':''}`,`data-index="${i}" aria-label="${face?esc(C.aac[c.key]):(i+1)+'번 그림 열기'}" ${g.matched.includes(c.key)||g.awaiting?'disabled':''}`);}).join('')}</div>`;controls=g.awaiting?button('mini-reset','살펴봤어요. 다시 뒤집기','primary wide'):'';}
 if(g.kind==='matching'){title='상황과 안전 행동을 연결해요';description='왼쪽 그림 하나, 오른쪽 행동 하나를 골라 짝을 맞춰요.';const col=(side,order)=>`<div class="match-column"><h3>${side==='left'?'이럴 때':'이렇게 해요'}</h3>${order.map(i=>{const p=g.pairs[i];return button(side==='left'?'mini-match-left':'mini-match-right',`${aacImage(side==='left'?p.leftKey:p.rightKey)}<span>${esc(side==='left'?p.left:p.right)}</span>`,`match-card ${g.matched.includes(i)?'matched':''} ${side==='left'&&g.selected===i?'selected':''}`,`data-index="${i}" ${g.matched.includes(i)?'disabled':''} aria-pressed="${g.matched.includes(i)||side==='left'&&g.selected===i}"`);}).join('')}</div>`;board=`<div class="matching-grid">${col('left',[0,1,2])}${col('right',g.rightOrder)}</div>`;}
 if(g.kind==='dodge'){title='위험 구역을 피해 걸어요';description='안전한 칸으로 이동해 다섯 걸음 도착해요.';const obstacles=g.complete?[]:G.dodgeRounds[g.round];board=`<div class="dodge-field" id="dodge-field" aria-label="왼쪽·가운데·오른쪽 세 칸의 산책 게임 지도"><div class="dodge-lanes">${[0,1,2].map(lane=>`<div class="dodge-lane ${g.lane===lane?'active':''}">${obstacles.filter(h=>h.lane===lane).map(h=>`<div class="dodge-hazard">${image('media/game/'+h.key+'.webp',G.hazardNames[h.key])}<b>${G.hazardNames[h.key]}</b></div>`).join('')}</div>`).join('')}</div>${image('media/illustrations/sprite-hero.png','안전한 길을 고르는 형아맨','dodge-hero',`style="left:${[16.7,50,83.3][g.lane]}%"`)}<div class="dodge-progress">안전한 걸음 ${g.round} / 5</div></div><p class="scene-caption">화면의 길을 터치하거나 아래 이동 버튼을 눌러요. 실제 뱀·벌은 가까이 가지 않고 선생님께 알려요.</p>`;controls=`<div class="dodge-controls">${['왼쪽으로','가운데로','오른쪽으로'].map((t,i)=>button('mini-lane',t,'secondary',`data-index="${i}" aria-pressed="${g.lane===i}"`)).join('')}</div>${button('mini-step','앞으로 한 걸음','primary wide')}`;}
 return `<section class="mini-game"><div class="section-head"><div><p class="eyebrow">목표가 있는 터치 미션</p><h2 id="mini-title" tabindex="-1">${title}</h2><p>${description}</p></div><span class="tag">${g.complete?'미션 완료':'천천히 해도 괜찮아요'}</span></div>${board}<div class="mini-notice" role="status">${esc(g.notice)}</div>${g.complete?button('mini-finish','미션 완료! 다음으로','primary wide'):controls}${g.kind==='torch'?'<p class="sim-note">안전장치 위치를 알아보는 훈련이에요. 실제 화재 때는 물건이나 소화기를 찾느라 대피를 늦추지 않고, 담당자의 안내를 따라요.</p>':''}<div class="actions">${button('mini-next','선생님과 다음 활동으로','text-button')}</div></section>`;
}
function startChoice(){session.phase=moduleQuestions(moduleId()).length?'choice':'quiz';session.questionIndex=0;feedback=null;render();}
function startMiniOrChoice(){session.mini=G.create(moduleId());if(session.mini){session.phase='mini';feedback=null;render();}else startChoice();}
function chooseActivity(kind){if(kind==='prep'){session.phase='play';session.gameCards=[];session.gameNotice='';session.questionIndex=0;feedback=null;render();return;}session.mini=G.create(moduleId(),kind);if(session.mini){session.phase='mini';feedback=null;render();}else startChoice();}
function miniAction(action,value){if(!session?.mini)return;G.act(session.mini,action,value);render(false);main.querySelector('[data-action="mini-finish"]')?.focus();}
function jump(){const g=session.mini;if(g.phase!=='ready'||g.inAir||g.complete)return;G.act(g,'jump');const el=$('#jump-hero'),btn=main.querySelector('[data-action="mini-jump"]');if(btn)btn.disabled=true;const begin=performance.now();function frame(now){if(page!=='learn'||session.mini!==g||session.phase!=='mini'){g.inAir=false;return;}const p=pref.motion?Math.min(1,(now-begin)/650):1;if(el)el.style.transform=`translateY(${-Math.sin(Math.PI*p)*110}px)`;if(p<1)requestAnimationFrame(frame);else{G.act(g,'land');render(false);main.querySelector('[data-action="mini-jump"],[data-action="mini-rest"]')?.focus();}}requestAnimationFrame(frame);}
function renderQuestion(){const id=moduleId(),q=currentQuestion(),isQuiz=session.phase==='quiz';const list=isQuiz?C.places[id].quizzes:moduleQuestions(id);const title=isQuiz?'확인 퀴즈':'상황 게임';
 const visual=id==='escape'?escapeMap(q):`${image(scene(id),C.places[id].title+' 상황 안내 그림','question-image')}<p class="sim-note">선택하면 어떤 행동이 안전한지 함께 확인해요.</p><div class="simulation-map" aria-label="미션 진행"><div class="map-node ${session.questionIndex===0?'selected':''}">상황 확인</div><div class="map-node ${session.questionIndex>0?'selected':''}">행동 선택</div><div class="map-node ${feedback?.right?'selected':''}">안전 약속</div></div>`;
 let answers='';
 if(!feedback){if(q.kind==='report')answers=`<div class="checklist">${q.options.map((t,i)=>`<label class="report-check"><input type="checkbox" data-report="${i}" ${selectedReports.has(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div>${button('report-check','신고할 내용 확인','primary wide')}`;
 else if(isQuiz)answers=`<div class="options ox">${button('answer','<strong aria-hidden="true">O</strong><span>맞아요</span>','option','data-index="true" aria-label="맞아요, O"')}${button('answer','<strong aria-hidden="true">X</strong><span>아니에요</span>','option','data-index="false" aria-label="아니에요, X"')}</div>`;
 else answers=options(q);
 answers+=`<div class="actions">${button('hint','설명 먼저 보기','secondary')}${button('read','문제 읽기','secondary')}</div>${hints.has(questionKey())?`<div class="info" style="margin-top:18px">${esc(q.why)}</div>`:''}`;
 }else answers=`<div class="feedback ${feedback.right?'':'retry'}" role="status"><h3>${feedback.right?(q.kind==='support'?'내게 맞는 도움을 알려줬어요.':q.kind==='report'?'구조 요청 내용을 확인했어요.':'안전한 행동을 확인했어요.'):'괜찮아요. 함께 다시 알아봐요.'}</h3><p>${esc(q.why)}</p>${feedback.right?button('next-question','다음으로','primary wide'):`<div class="actions">${button('try-again','다시 골라보기','primary')}${button('guided','함께 확인했어요','secondary')}</div>`}</div>`;
 return `<div class="question-layout"><div class="question-visual">${visual}</div><section class="question-box"><p class="eyebrow">${title} ${session.questionIndex+1} / ${list.length}${q.kind==='report'?' · 실제 전화 연결 없음':''}</p><h2 class="q-text" tabindex="-1">${esc(q.prompt)}</h2>${answers}</section></div>`;
}
function escapeMap(q){const blocked=q.id==='blocked',assembly=q.id==='assembly';return `<div class="simulation-map" role="img" aria-label="${blocked?'복도에 연기가 있어 선생님과 사전 확인한 안전한 공간에서 구조를 요청하는 장면':assembly?'안전한 집결지에서 인원을 확인하며 기다리는 장면':'담당자의 안내와 사전 피난계획을 확인하는 대피 연습 지도'}"><div class="map-node ${q.id==='alarm'?'selected':''}">숙소 방</div><div class="map-node ${blocked?'blocked':''}">복도${blocked?'<br>연기 · 진입하지 않아요':''}</div><div class="map-node ${q.id==='clear'?'selected':''}">확인된<br>대피 경로</div><div class="map-node ${q.id==='mobility'?'selected':''}">담당자와<br>이동 지원</div><div class="map-node ${blocked||q.id==='call'?'selected':''}">사전 확인한<br>안전한 공간</div><div class="map-node ${assembly?'selected':''}">집결지와<br>인원 확인</div></div><p class="sim-note">학교·숙소의 실제 피난계획과 담당자의 안내를 따라요. 그림은 위치를 설명하는 연습 지도예요.</p>${image(scene('escape'),'형아맨과 선생님이 대피 안내를 확인해요.','question-image')}`;}
function finishModule(){M.completeModule(session,moduleId());session.phase='module-done';feedback=null;render();}
function nextQuestion(){feedback=null;selectedReports.clear();session.questionIndex++;if(session.single){const qs=session.phase==='quiz'?C.places[moduleId()].quizzes:moduleQuestions(moduleId());if(session.questionIndex>=qs.length)return finishActivity();render();return;}const qs=session.phase==='quiz'?C.places[moduleId()].quizzes:moduleQuestions(moduleId());if(session.questionIndex>=qs.length){if(session.phase==='choice'){session.phase='quiz';session.questionIndex=0;}else{return finishModule();}}render();}
function answer(value,assisted=false){const q=currentQuestion(),kind=session.phase==='quiz'?'quiz':q.kind||'choice';const correct=q.kind==='support'?true:(session.phase==='quiz'?value===q.answer:value===q.correct);
 if(q.kind==='support')session.supportChoice=q.options[value];else M.recordAttempt(session,moduleId(),q.id,correct,{kind,assisted:assisted||hints.has(questionKey())});
 feedback={right:correct};render(false);const target=main.querySelector('.feedback');if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',behavior:pref.motion?'smooth':'auto'});}}
function renderResult(){const sm=M.summary(session);return `${heading('오늘의 안전교육 결과','안전의 달인,<br>함께 연습했어요.',session.single?'선택한 활동의 기록이에요. 아래 약속은 이 장소의 복습 자료예요.':'다시 확인한 것도 배움이에요. 실제 장소에서도 안전 약속을 실천해요.')}${session.single&&!sm.total?`<div class="metric-grid game-result"><div class="metric">${icon("result")}<strong>활동 완료</strong>${esc(session.activityTitle)}</div><div class="metric"><strong>${session.activityAssisted?"함께 확인":"끝까지 연습"}</strong>${session.activityAssisted?"도움을 받아 안전 약속을 확인했어요.":"오늘의 목표가 있는 활동을 마쳤어요."}</div></div>`:`<div class="metric-grid"><div class="metric"><strong>${sm.completed} / ${sm.modules}</strong>${session.single?'연습한 활동':'마친 안전 미션'}</div><div class="metric"><strong>${sm.independent}</strong>스스로 확인한 문제</div><div class="metric"><strong>${sm.guided}</strong>함께 다시 확인한 문제</div></div>`}<details class="no-print"><summary>선생님: 결과 읽는 방법</summary><p class="info">상황 게임·확인 퀴즈의 첫 응답과 설명 사용 여부를 기준으로 구분한 수업 기록입니다. 실제 장소에서의 안전 행동은 별도로 관찰하고 필요한 지원과 함께 확인해 주세요.</p></details><section class="section panel soft"><h2>나의 안전 약속</h2><p>실제 장소에서 기억할 약속을 하나 골라요.</p><div class="pledge no-print">${[['help','도움이 필요하면 알려요.'],['together','정해진 곳에서 함께 움직여요.'],['stop','위험하면 멈추고 확인해요.']].map(([key,text])=>button('pledge',`${aacImage(key)}<span>${text}</span>`,'',`data-key="${key}" aria-pressed="${pledge===key}"`)).join('')}</div><p id="my-pledge" style="margin-top:18px;font-weight:800">${pledge?`나의 약속: ${esc(C.aac[pledge])}`:'기억하고 싶은 약속을 골라요.'}</p></section><section class="section"><label>이름 <span class="muted">(선택 · 저장하거나 전송하지 않아요)</span><input class="print-name" id="student-name" type="text" maxlength="30" autocomplete="off" placeholder="결과에 표시할 이름"></label></section><div class="actions no-print">${button('print','결과 인쇄·PDF 저장','primary')}${button('download','학습 결과 파일 저장','secondary')}${button('review-guided','함께 확인한 문제 보기','secondary')}</div><section class="rule-summary" aria-label="오늘 배운 안전 약속">${session.route.map(id=>`<div class="panel"><h3>${esc(C.places[id].title)}</h3><ul>${C.places[id].spots.map(s=>`<li>${esc(s.rule)}</li>`).join('')}</ul></div>`).join('')}</section><div class="actions no-print">${button('restart','같은 수업 다시 하기','secondary')}${button('home','다른 장소도 배우기','secondary')}</div>`;}
function aacImage(key){return image(`media/illustrations/aac-${key}.webp`,'','',`data-aac="${esc(key)}"`);}
function openDialog(kind,html){returnFocus=document.activeElement;dialogKind=kind;$('#dialog-body').innerHTML=html;if(!dialog.open){if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');}$('#dialog-body button')?.focus();}
function closeDialog(){if(dialog.close)dialog.close();else dialog.removeAttribute('open');window.speechSynthesis?.cancel();dialogKind='';if(returnFocus?.isConnected)returnFocus.focus();else main.querySelector('h1')?.focus({preventScroll:true});}
function dialogHead(title){return `<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('close','닫기','secondary')}</div>`;}
function spotDialog(id){const s=currentPlace().spots.find(s=>s.id===id);openDialog('spot',`${dialogHead(esc(s.title))}<div class="spot-detail">${aacImage(s.signal)}<p>${esc(s.rule)}</p></div><div class="actions">${button('spot-read','설명 듣기','secondary',`data-id="${id}"`)}${button('spot-done','확인했어요','primary',`data-id="${id}"`)}</div>`);}
function aacDialog(){openDialog('aac',`${dialogHead('그림으로 말해요')}<p class="muted">내가 하고 싶은 말을 골라요.</p><div class="aac-tabs" role="group" aria-label="말하기 종류">${C.aacGroups.map((g,i)=>button('aac-tab',g.title,'secondary',`data-index="${i}" aria-pressed="${i===aacTab}"`)).join('')}</div><div class="aac-grid">${C.aacGroups[aacTab].keys.map(key=>button('say',`${aacImage(key)}<span>${C.aac[key]}</span>`,'aac-card',`data-key="${key}"`)).join('')}</div>`);}
function settingsDialog(){openDialog('settings',`${dialogHead('나에게 맞게 배워요')}${[['pictures','그림으로 함께 보기','말하기 그림과 쉬운 안내를 함께 사용해요.'],['large','글자 크게 보기','글자와 버튼을 더 크게 보여줘요.'],['voice','소리로 읽기','누를 때 한국어로 읽어줘요.'],['motion','게임 동작 보기','끄면 점프 동작을 정지 그림으로 확인해요.'],['remember','이 기기에 활동 배지 기억하기','이름 없이 장소별 활동 완료만 보관해요. 공용 기기는 끄고 사용해요.']].map(([key,title,desc])=>`<label class="setting-row"><span><strong>${title}</strong><p>${desc}</p></span><input type="checkbox" data-setting="${key}" ${pref[key]?'checked':''}></label>`).join('')}<p class="info" style="margin-top:20px">천천히 선택해도 괜찮아요. 키보드를 사용할 때는 Tab으로 이동하고 Enter 또는 Space로 골라요.</p>`);}
function teacherDialog(){const p=C.places[config.place];openDialog('teacher',`${dialogHead('선생님 수업 도구')}<p>장소에서 필요한 활동을 바로 골라 사용합니다. 그림 찾기·미니게임·상황·퀴즈·영상은 독립 활동이며 모두 할 필요는 없습니다. 연결 수업은 선택한 일정에 따라 진행합니다.</p><p class="info" style="margin-top:17px">말·AAC·손짓·시선·교사의 대리 선택을 모두 응답 방법으로 활용할 수 있습니다. 실제 장소의 인솔·이동·건강·감각 지원 계획과 함께 사용하세요.</p>${p?`<section class="panel" style="margin-top:17px"><h3>${esc(p.title)} 수업 준비</h3><p>${esc(p.teacher)}</p></section>`:''}<section class="panel section"><h3>연결 수업의 이동 자료 · 선생님 설정</h3><p class="muted">학생에게 동의나 확인을 요구하는 단계가 아닙니다. 일정에 필요한 자료만 추가하세요.</p><label class="setting-row"><span>버스 이동 자료 추가</span><input type="checkbox" data-route="move" ${config.move==='bus'?'checked':''}></label>${config.type==='overnight'?`<label class="setting-row"><span>일정에 휴게소가 있어요</span><input type="checkbox" data-route="rest" ${config.rest?'checked':''}></label>`:''}${button('clear-progress','이 기기의 활동 배지 기록 지우기','secondary')}</section><div class="actions">${button('all-resources','전체 영상·자료 찾기','primary')}${button('source-info','자료 출처·사용 안내','secondary')}</div><h3 style="margin-top:25px">장소별 바로 공유</h3><p class="muted">해당 장소만 바로 열리는 주소예요.</p><div class="teacher-links">${[...C.destinations,'bus','rest','night','escape'].map(id=>`<a href="${esc(M.shareURL(BASE,{type:id==='lodging'||id==='night'||id==='escape'?'overnight':'halfday',place:id,scope:'place'},C))}" target="_blank" rel="noopener noreferrer">${esc(C.places[id].title)} <span class="sr-only">새 창</span> ${icon('open')}</a>`).join('')}</div>`);}
function sourceDialog(){openDialog('sources',`${dialogHead('자료 출처·사용 안내')}<p>경기도교육청 나.침.반 자료와 공공기관 안전수칙을 참고하여 특수학교 현장학습에 맞게 재구성했습니다.</p><ul><li>2026학년도 영상 링크 안내: 원문 ${R.meta.sourceVideoCount||773}개 수록 항목. 중복 수록을 보존했어요.</li><li>2016년 체험형 우수사례: 교사가 수업을 설계할 때 참고할 활용안으로 연결했어요.</li><li>장소 연결은 제목·주제에 따른 추천이며, 영상 전체 내용·현재 공개·자막의 검증을 뜻하지 않아요.</li><li>발달단계는 권장 정보예요. 학생의 이해·의사소통·감각 특성에 맞춰 선택해 주세요.</li><li>문화유산은 직접 전용 자료 대신 관람 전 공통 안전 자료를 연결했어요.</li></ul><p>학생 이름·응답은 서버로 전송하지 않아요. 학습지원 설정은 이 브라우저에 보관하며, 활동 배지는 학습지원에서 기억하기를 켰을 때만 보관해요. 외부 영상은 해당 제공 사이트에서 열립니다.</p><div class="actions"><a class="link-button" href="https://www.korea.kr/news/policyNewsView.do?newsId=148938057" target="_blank" rel="noopener noreferrer">행정안전부 다중이용시설 화재 행동요령 ${icon('open')}</a></div>`);}
function openResources(id,all=false){returnPage=page;resourceFilter.place=id||'';resourceMode=all?'all':'related';resourcePage=0;closeIfOpen();page='resources';render();}
function closeIfOpen(){if(dialog.open)closeDialog();}
function resourceItems(){let videos=R.videos;if(resourceMode==='related')videos=videos.filter(v=>v.studentRecommended&&!v.teacherOnly);const filtered=M.filterVideos(videos,resourceFilter);const ids=preferred[resourceFilter.place]||[];return filtered.sort((a,b)=>{const ai=ids.indexOf(a.id),bi=ids.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);});}
function renderResources(){const items=resourceItems(),perPage=9,total=Math.max(1,Math.ceil(items.length/perPage));resourcePage=Math.min(resourcePage,total-1);const shown=items.slice(resourcePage*perPage,(resourcePage+1)*perPage);const relatedTitle=resourceFilter.place?C.places[resourceFilter.place]?.title:'';return `${heading(resourceMode==='all'?'선생님 자료실':'장소와 함께 보는 영상',relatedTitle?`${esc(relatedTitle)} 관련 자료`:'안전 영상·체험 자료','그림과 영상으로 확인하고, 안전한 행동을 다시 연습해요.')}<div class="actions no-print">${button('back-from-resources','학습 화면으로 돌아가기','primary')}${resourceMode==='related'?button('all-resources','선생님 전체 자료실','secondary'):''}${button('share-resources','이 자료 목록 주소 공유','secondary')}</div><div class="info" style="margin-top:24px">${resourceMode==='all'?'교사용 전체 목록입니다. 민감한 주제와 뉴스·사고 사례도 포함합니다. ':''}영상의 내용·현재 재생 여부·자막·소리와 장면은 수업 전에 확인해 주세요. 발달단계는 권장 정보이며 교사가 선택할 수 있어요.${resourceFilter.place==='heritage'?'<br>문화유산 전용 영상이 아니라 관람 전에 함께 볼 공통 안전 자료입니다.':''}</div><form id="resource-filters" class="filters" aria-label="자료 찾기"><label class="search-filter">제목·주제 검색<input name="query" type="search" value="${esc(resourceFilter.query)}" placeholder="예: 버스, 화재, 폭염" autocomplete="off"></label><label>장소<select name="place"><option value="">모든 장소</option>${Object.entries(C.places).map(([id,p])=>`<option value="${id}" ${resourceFilter.place===id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><label>안전영역<select name="domain"><option value="">모든 영역</option>${(R.meta.domains||[]).map(d=>`<option ${resourceFilter.domain===d?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label>발달단계<select name="level"><option value="">모든 단계</option>${Object.entries(levelName).map(([id,n])=>`<option value="${id}" ${resourceFilter.level===id?'selected':''}>${n}</option>`).join('')}</select></label><button type="submit" class="primary illustrated-button">${icon('search')}<span>자료 찾기</span></button></form><div class="resource-count"><strong>${items.length}개 수록 항목</strong><span class="muted">원문 중복 수록 포함</span></div><div class="video-grid">${shown.map(videoCard).join('')}</div>${items.length?'':`<div class="empty"><p>이 조건에 맞는 자료가 없어요.</p>${button('clear-filters','조건 지우고 다시 찾기','secondary')}</div>`}<div class="pagination">${button('resource-prev','이전','secondary',resourcePage===0?'disabled':'')}<span>${resourcePage+1} / ${total}</span>${button('resource-next','다음','secondary',resourcePage>=total-1?'disabled':'')}</div>${renderActivities()}<p class="muted" style="font-size:14px;margin-top:22px">출처: 경기도교육청 나.침.반 영상 링크 안내 및 체험형 프로그램. 영상·썸네일의 권리는 원 제공자에게 있습니다.</p>`;}
function videoCard(v){const url=M.safeURL(v.url);return `<article class="video-card"><div class="video-thumb ${v.thumbnail?'has-image':''}"><div class="thumb-fallback">${icon('play')}<span class="sr-only">영상 미리보기 없음</span></div>${v.thumbnail?image(v.thumbnail,'원본 영상 썸네일: '+v.title,'','data-thumbnail="true" referrerpolicy="no-referrer"'):''}</div><div class="video-copy"><div class="meta-line"><span>${esc(v.domain)}</span><span>${esc(v.duration||'시간 정보 없음')}</span>${v.teacherOnly?'<span>교사 사전 확인</span>':''}</div><h3>${esc(v.title)}</h3><p>${esc(v.provider)}<br>${esc((v.levels||[]).map(l=>levelName[l]||l).join(' · '))}</p><p>주제: ${esc(v.topic)}</p><details><summary>출처 정보</summary><small>${esc(v.sourceDoc)}<br>${esc(v.sourceRow||'사용자 제공 링크')}</small></details>${url?`<a class="link-button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">영상 보기 <span class="sr-only">외부 사이트 새 창</span> ${icon('open')}</a>`:'<p>원문 링크를 다시 확인해 주세요.</p>'}</div></article>`;}
function renderActivities(){const items=R.activities.filter(a=>(!resourceFilter.place||(a.venues||[]).includes(resourceFilter.place))).slice(0,6);return items.length?`<section class="section"><h2>보고 나서 함께 해봐요</h2><p class="muted">체험형 자료를 오늘의 장소에 맞춰 재구성한 활동 아이디어예요.</p><div class="activity-grid">${items.map(a=>`<article class="panel activity"><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><details><summary>출처 확인</summary><small>${esc(a.sourceDoc)}<br>${esc(a.note||'')}</small></details></article>`).join('')}</div></section>`:'';}
async function share(scope,view){const c={...config,scope};if(view){c.place=resourceFilter.place||config.place;c.scope='place';}const u=new URL(M.shareURL(BASE,c,C,view));if(view){if(resourceMode==='all')u.searchParams.set('catalog','all');for(const k of ['domain','level','query'])if(resourceFilter[k])u.searchParams.set(k,resourceFilter[k]);}const url=u.href;try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(url);notify('공유 주소를 복사했어요.');}catch{openDialog('share',`${dialogHead('공유 주소')}<p>아래 주소를 선택해서 복사해 주세요.</p><label class="sr-only" for="share-url">공유할 주소</label><input id="share-url" class="copy-field" readonly value="${esc(url)}">`);$('#share-url').select();}}
function reviewDialog(){const rows=session.records.filter(r=>r.complete&&r.assisted);openDialog('review',`${dialogHead('함께 다시 확인한 문제')}${rows.length?rows.map(r=>{const p=C.places[r.module],q=[...p.choices,...p.quizzes,...(r.module==='escape'?C.evacuation:[])].find(q=>q.id===r.item);return `<section class="panel" style="margin-top:12px"><h3>${esc(p.title)}</h3><p>${esc(q?.prompt||r.item)}</p><p class="muted" style="margin-top:12px">${esc(q?.why||'')}</p></section>`;}).join(''):'<p>이번 수업에서는 첫 응답과 설명 사용 기준으로 함께 확인한 문제가 없었어요. 실제 장소에서도 약속을 다시 확인해요.</p>'}`);}
function download(){const payload={activity:session.activityKind||null,activityAssisted:session.activityAssisted||false,game:session.mini||session.find||session.difference||null,app:'안전의 달인',version:C.version,date:new Date().toISOString(),type:session.config.type,place:session.config.place,route:session.route,summary:M.summary(session),pledge:C.aac[pledge]||'',name:$('#student-name')?.value.trim()||'',records:session.records,supportExpression:session.supportChoice,note:'첫 응답과 설명 사용 기준의 수업 기록이며 실제 안전 수행 평가를 대신하지 않습니다.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='안전의달인_학습결과.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('이 기기에 학습 결과 파일을 저장했어요.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,key=b.dataset.key;
 switch(a){
 case 'badge':badgeDialog(id);break;
 case 'start-activity':startActivity(b.dataset.kind);break;
 case 'open-world':world={place:config.place,x:12,y:87};setPage('world');break;
 case 'world-move':moveWorld(+b.dataset.dx,+b.dataset.dy);break;
 case 'world-nearest':{const n=[19,50,81].map((x,i)=>({i,d:Math.abs(world.x-x)})).sort((a,b)=>a.d-b.d)[0].i;startActivity(A.worlds[config.place].activities[n],true);break;}
 case 'world-mission':startActivity(b.dataset.kind,true);break;
 case 'activity-home':setPage(session?.fromWorld&&world?.place===config.place?'world':'place');break;
 case 'activity-result':setPage('result');break;
 case 'find-target':foundTarget(id);break;
 case 'find-region':foundTarget(id,true);break;
 case 'find-hint':{const g=session.phase==='difference'?session.difference:session.find;g.hint=!g.hint;if(g.hint)g.assisted=true;render(false);main.querySelector('[data-action="find-hint"]')?.focus();break;}
 case 'find-egg':session.find.egg=true;notify('숨은 관찰 그림 발견! '+A.finds[moduleId()].egg.label+'도 보였네요.');break;
 case 'find-finish':if(session.find.found.length===A.finds[moduleId()].targets.length){if(session.single)finishActivity();else startChoice();}break;
 case 'difference-region':{const d=differences.find(d=>d.id===id),g=session.difference;if(!d)break;if(!g.found.includes(id))g.found.push(id);g.assisted=g.assisted||b.dataset.assisted==='true'||g.hint;render(false);openDialog('difference-rule',`${dialogHead(esc(d.label)+' 정리')}<div class="spot-detail">${aacImage(d.signal)}<p>${esc(d.rule)}</p></div>${button('close','다시 살펴볼게요','primary wide')}`);break;}
 case 'activity-finish':if(session.difference.found.length===3)finishActivity();break;
 case 'mini-pick':miniAction('pick',+b.dataset.index);break;
 case 'clear-progress':activityProgress={};try{localStorage.removeItem('safetyMasterActivities');}catch{}notify('이 기기의 활동 배지 기록을 지웠어요.');break;
 case 'home':closeIfOpen();setPage('home');break;
 case 'type':config={type:id,place:null,scope:'lesson',move:'none',rest:false};chosenType=true;render(false);$('#places-title')?.focus({preventScroll:true});$('#places')?.scrollIntoView({block:'start',behavior:pref.motion?'smooth':'auto'});break;
 case 'place':closeIfOpen();config={...config,type:id==='lodging'?'overnight':config.type,place:id,scope:'lesson'};setPage('place');break;
 case 'choose-again':chosenType=true;setPage('home');break;
 case 'prepare':config.scope='lesson';setPage('prepare');break;
 case 'pre-pledge':b.setAttribute('aria-pressed','true');say(b.textContent);break;
 case 'begin-goal':if(config.move==='bus'||config.rest)config.scope='lesson';session=M.createSession(config,C);goalAnswered=false;goalChoice=null;pledge='';hints.clear();setPage('goal');break;
 case 'goal-answer':goalChoice=+b.dataset.index;goalAnswered=true;M.recordAttempt(session,config.place,goalQuestion().id,goalChoice===goalQuestion().correct,{kind:'goal'});render(false);main.querySelector('.feedback button')?.focus();break;
 case 'start-learning':session.phase='explore';session.index=0;setPage('learn');break;
 case 'spot':spotDialog(id);break;
 case 'spot-read':say(currentPlace().spots.find(s=>s.id===id).rule);break;
 case 'spot-done':if(!session.spotIds.includes(id))session.spotIds.push(id);closeDialog();render(false);if(session.spotIds.length===currentPlace().spots.length)main.querySelector('[data-action="to-game"]')?.focus();else main.querySelector('.spot-button:not(.done)')?.focus();break;
 case 'to-game':if(['bus','lodging','theme-park','rest'].includes(moduleId())){session.find={found:[],hint:false,egg:false};session.phase='find';render();}else if(moduleId()==='escape')startMiniOrChoice();else if(G.catalog(moduleId()).length){session.phase='activity-menu';render();}else startChoice();break;
 case 'game-card':{const spot=currentPlace().spots.find(s=>s.id===id);if(spot){if(!session.gameCards.includes(id))session.gameCards.push(id);session.gameNotice='안전한 준비예요. '+spot.rule;}else{session.gameNotice='이 행동은 위험할 수 있어요. 안전 약속에서 확인한 행동을 다시 골라봐요.';}render(false);main.querySelector('.game-notice')?.scrollIntoView({block:'nearest'});if(session.gameCards.length===3)main.querySelector('[data-action="game-finish"]')?.focus();else main.querySelector('[data-action="game-card"]:not(:disabled)')?.focus();break;}
 case 'game-finish':if(session.single)finishActivity();else startChoice();break;
 case 'choose-mini':chooseActivity(b.dataset.kind);break;
 case 'mini-flip':{const card=session.mini.cards[+b.dataset.index];miniAction('flip',+b.dataset.index);if(pref.voice&&card&&(session.mini.open.includes(+b.dataset.index)||session.mini.matched.includes(card.key)))say(C.aac[card.key]);break;}
 case 'mini-reset':miniAction('reset');break;
 case 'mini-match-left':miniAction('left',+b.dataset.index);break;
 case 'mini-match-right':miniAction('right',+b.dataset.index);break;
 case 'mini-lane':miniAction('lane',+b.dataset.index);break;
 case 'mini-step':miniAction('step');break;
 case 'mini-wait':miniAction('wait');main.querySelector('[data-action="mini-jump"]')?.focus();break;
 case 'mini-jump':jump();break;
 case 'mini-rest':miniAction('rest');break;
 case 'mini-find':miniAction('find',id);break;
 case 'mini-bright':miniAction('bright');break;
 case 'mini-move':miniAction('move',+b.dataset.index);break;
 case 'mini-hazard':miniAction('hazard');break;
 case 'mini-finish':if(session.single)finishActivity();else startChoice();break;
 case 'mini-next':if(session.single)finishActivity(true);else startChoice();break;
 case 'answer':answer(session.phase==='quiz'?b.dataset.index==='true':+b.dataset.index);break;
 case 'hint':hints.add(questionKey());render(false);say(currentQuestion().why);main.querySelector('[data-action="answer"]')?.focus();break;
 case 'try-again':feedback=null;render(false);main.querySelector('[data-action="answer"]')?.focus();break;
 case 'guided':{const q=currentQuestion();answer(session.phase==='quiz'?q.answer:q.correct,true);break;}
 case 'report-check':if(selectedReports.size<3){notify('위치·상황·필요한 도움을 모두 골라요.');return;}session.reported=[...selectedReports];feedback={right:true};render(false);main.querySelector('[data-action="next-question"]')?.focus();break;
 case 'next-question':nextQuestion();break;
 case 'next-module':if(session.index+1>=session.route.length){setPage('result');}else{session.index++;session.phase='explore';session.spotIds=[];session.questionIndex=0;feedback=null;render();}break;
 case 'resume':config={...session.config};setPage('learn');break;
 case 'restart':config={...session.config};if(session.single)startActivity(session.activityKind,session.fromWorld);else setPage('prepare');break;
 case 'pledge':{const name=$('#student-name')?.value||'';pledge=key;render(false);if($('#student-name'))$('#student-name').value=name;main.querySelector(`[data-action="pledge"][data-key="${key}"]`)?.focus();say(C.aac[key]);break;}
 case 'settings':settingsDialog();break;
 case 'aac':aacDialog();break;
 case 'aac-tab':aacTab=+b.dataset.index;{const old=returnFocus;aacDialog();returnFocus=old;$('#dialog-body [data-action="aac-tab"][aria-pressed="true"]')?.focus();}break;
 case 'say':say(C.aac[key]||'도와주세요');notify(C.aac[key]||'도와주세요');break;
 case 'read':{const surface=dialog.open?$('#dialog-body'):main;let text;if(page==='learn'&&!dialog.open&&['choice','quiz'].includes(session.phase)){const q=currentQuestion();text=q.prompt+'. '+(feedback?q.why:session.phase==='quiz'?'맞아요, O. 아니에요, X.':q.options.join('. '));}else text=[...surface.querySelectorAll('h1,h2,h3,.intro,.spot-detail p,.q-text,.feedback p,.scene-caption,.mini-notice,.game-notice,.section-head p')].map(e=>e.textContent).join('. ');say(text||surface.textContent);break;}
 case 'teacher':teacherDialog();break;
 case 'source-info':sourceDialog();break;
 case 'close':closeDialog();break;
 case 'related':openResources(id||moduleId());break;
 case 'resources':openResources(config.place||'',false);break;
 case 'all-resources':resourceMode='all';resourcePage=0;resourceFilter.place='';if(page!=='resources'){returnPage=page;closeIfOpen();page='resources';}resourceFilter.domain='';render();break;
 case 'back-from-resources':page=returnPage==='resources'?'home':returnPage;render();break;
 case 'resource-next':resourcePage++;render();break;
 case 'resource-prev':resourcePage--;render();break;
 case 'clear-filters':resourceFilter={place:'',domain:'',level:'',query:''};resourcePage=0;render();break;
 case 'share-place':share('place');break;
 case 'share-lesson':share('lesson');break;
 case 'share-resources':share('place','resources');break;
 case 'print':window.print();break;
 case 'download':download();break;
 case 'review-guided':reviewDialog();break;
 }
});

document.addEventListener('pointermove',e=>{const field=e.target.closest?.('#torch-field');if(!field||session?.mini?.kind!=='torch')return;const r=field.getBoundingClientRect();field.style.setProperty('--light-x',((e.clientX-r.left)/r.width*100)+'%');field.style.setProperty('--light-y',((e.clientY-r.top)/r.height*100)+'%');});
document.addEventListener('pointerdown',e=>{const field=e.target.closest?.('#torch-field');if(!field||session?.mini?.kind!=='torch')return;const r=field.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;field.style.setProperty('--light-x',x+'%');field.style.setProperty('--light-y',y+'%');const t=G.targets.find(t=>Math.abs(t.x-x)<14&&Math.abs(t.y-y)<19);if(t)miniAction('find',t.id);});
document.addEventListener('pointerdown',e=>{const field=e.target.closest?.('#dodge-field');if(!field||session?.mini?.kind!=='dodge')return;const r=field.getBoundingClientRect();miniAction('lane',Math.max(0,Math.min(2,Math.floor((e.clientX-r.left)/r.width*3))));});
document.addEventListener('change',e=>{if(e.target.dataset.setting){pref[e.target.dataset.setting]=e.target.checked;if(!pref.voice)window.speechSynthesis?.cancel();applyPrefs();}if(e.target.dataset.route==='move'){config.move=e.target.checked?'bus':'none';}if(e.target.dataset.route==='rest'){config.rest=config.type==='overnight'&&e.target.checked;}if(e.target.dataset.setting==='remember'){if(pref.remember)storeProgress();else try{localStorage.removeItem('safetyMasterActivities');}catch{}}if(e.target.dataset.report!==undefined){const n=+e.target.dataset.report;if(e.target.checked)selectedReports.add(n);else selectedReports.delete(n);}});
document.addEventListener('submit',e=>{if(e.target.id==='resource-filters'){e.preventDefault();const f=new FormData(e.target);resourceFilter={place:f.get('place'),domain:f.get('domain'),level:f.get('level'),query:f.get('query')};resourcePage=0;render(false);main.querySelector('.resource-count')?.scrollIntoView({block:'start'});}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.thumbnail){e.target.closest('.video-thumb')?.classList.remove('has-image');e.target.remove();}},true);
document.addEventListener('keydown',e=>{if(page!=='world'||dialog.open||e.target.id!=='world-field')return;const d={ArrowLeft:[-8,0],ArrowRight:[8,0],ArrowUp:[0,-5],ArrowDown:[0,5]}[e.key];if(d){e.preventDefault();moveWorld(...d);}});
 document.addEventListener('click',e=>{if(session?.phase==='find'&&e.target.closest?.('#find-scene')&&!e.target.closest('[data-action]')){session.find.attempts++;session.find.notice='다른 곳도 천천히 살펴봐요. 힌트나 영역 버튼을 이용해도 괜찮아요.';const n=main.querySelector('.mini-notice');if(n)n.textContent=session.find.notice;}});
 dialog.addEventListener('cancel',()=>{window.speechSynthesis?.cancel();dialogKind='';});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
const initial=new URL(location.href);if(initial.searchParams.get('view')==='resources'){page='resources';resourceMode=initial.searchParams.get('catalog')==='all'?'all':'related';for(const k of ['domain','level','query'])resourceFilter[k]=initial.searchParams.get(k)||'';}
applyPrefs();render(false);
})();
